      "continuesAfterChunk": true,
      "id": "sec_9_sub_1",
      "kind": "unit",
      "parent": "sec_9",
      "sourceAnchors": [
        {
          "exactQuote": "9. ( 1 ) The Data Fiduciary shall, before processing any personal data of a child or a person with disability who has a lawful guardian obtain verifiable consent of the parent of such child or the lawful guardian, as the case may be, in such manner as may be prescribed.",
          "occurrence": 0,
          "sourceId": "src:188"
        },
        {
          "exactQuote": "Explanation. - For the purpose of this sub-section, the expression 'consent of the parent' includes the consent of lawful guardian, wherever applicable.",
